<script setup>
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { orderDetail, digitalContent, applyRefund as applyRefundApi } from '../../api/order'
import PageTitle from '../../components/PageTitle.vue'
const route=useRoute(),order=ref(null),loading=ref(false),content=ref(''),refundOpen=ref(false),refundBusy=ref(false),refundForm=reactive({reason:'',description:''})
async function load(){loading.value=true;try{order.value=await orderDetail(route.params.id)}finally{loading.value=false}}
async function getContent(){content.value=await digitalContent(order.value.orderNo);ElMessage.success('已获取数字内容授权链接')}
async function submitRefund(){if(!refundForm.reason.trim())return ElMessage.warning('请填写退款原因');refundBusy.value=true;try{await applyRefundApi({orderId:order.value.id,reason:refundForm.reason.trim(),description:refundForm.description.trim()||null,images:[]});refundOpen.value=false;ElMessage.success('退款申请已提交');await load()}finally{refundBusy.value=false}}
onMounted(load);watch(()=>route.params.id,load)
</script>
<template><PageTitle eyebrow="ORDER DETAIL" title="订单详情"/><div v-loading="loading" class="content-card" v-if="order"><el-descriptions :column="2" border><el-descriptions-item label="订单编号">{{order.orderNo}}</el-descriptions-item><el-descriptions-item label="订单状态">{{order.statusText}}</el-descriptions-item><el-descriptions-item label="商品">{{order.albumTitle}}</el-descriptions-item><el-descriptions-item label="商品形态">{{order.productType}}</el-descriptions-item><el-descriptions-item label="数量">{{order.quantity}}</el-descriptions-item><el-descriptions-item label="金额">¥ {{order.totalAmount}}</el-descriptions-item><el-descriptions-item label="收货人">{{order.receiverName||'数字内容订单'}}</el-descriptions-item><el-descriptions-item label="联系电话">{{order.receiverPhone||'—'}}</el-descriptions-item><el-descriptions-item label="收货地址" :span="2">{{order.receiverAddress||'—'}}</el-descriptions-item><el-descriptions-item label="物流" :span="2">{{order.carrier||'—'}} {{order.trackingNo||''}}</el-descriptions-item></el-descriptions><div class="actions" style="margin-top:20px"><el-button v-if="order.productType==='DIGITAL'&&[1,2].includes(Number(order.status))" type="primary" @click="getContent">获取数字内容</el-button><el-button v-if="[1,2,4].includes(Number(order.status))" @click="refundOpen=true">申请退款</el-button></div><p v-if="content" class="content-card">{{content}}</p><el-dialog v-model="refundOpen" title="申请退款" width="min(560px,92vw)"><el-form label-position="top"><el-form-item label="退款原因"><el-input v-model="refundForm.reason" maxlength="100" placeholder="简要说明退款原因"/></el-form-item><el-form-item label="详细说明"><el-input v-model="refundForm.description" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="refundOpen=false">取消</el-button><el-button type="primary" :loading="refundBusy" @click="submitRefund">提交申请</el-button></template></el-dialog></div></template>
